/* Cryptids & Mythology set additions — cards appended after cryptids.js.
   (cryptids.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'cryptids.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('cryptids');
  if (!S) return;
  var extra = [{"name":"Owlman","rarity":"uncommon","id":"owlman","subtitle":"Cryptid","details":"In 1976, witnesses near Mawnan, Cornwall reported a large, feathered, owl-like figure with glowing red eyes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eurasian%20eagle-owl%20%2844088%29.jpg?width=1024"},{"name":"Beast of Bodmin","rarity":"uncommon","id":"beast-of-bodmin","subtitle":"Cryptid","details":"Reports since the 1970s describe a large black cat roaming Cornwall's Bodmin Moor, far from any native big-cat range.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20Panther.JPG?width=1024"},{"name":"Surrey Puma","rarity":"uncommon","id":"surrey-puma","subtitle":"Cryptid","details":"Reports of a puma at large in Surrey began in the 1960s, launching decades of British big-cat sightings and searches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Felicity%20Inverness%20Museum.JPG?width=1024"},{"name":"Morbach Monster","rarity":"uncommon","id":"morbach-monster","subtitle":"Cryptid","details":"At Morbach, Germany, a 1988 air-base sighting revived tales of a werewolf-like beast tied to a candlelit shrine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scandinavian%20grey%20wolf%20Canis%20lupus.jpg?width=1024"},{"name":"Barmanou","rarity":"uncommon","id":"barmanou","subtitle":"Cryptid","details":"Reports from Pakistan's Chitral mountains describe a tall, hairy, ape-like wildman said to haunt high valleys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Gorilla%20-%20Du%20Chaillu.jpg?width=800"},{"name":"Ebu Gogo","rarity":"uncommon","id":"ebu-gogo","subtitle":"Cryptid","details":"Flores Island traditions in Indonesia tell of small, hairy, cave-dwelling folk said to have lived beside villagers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Homo%20floresiensis%20-%20facial%20approximation%20-%20color%202.jpg?width=1024"},{"name":"Moehau","rarity":"uncommon","id":"moehau","subtitle":"Cryptid","details":"Reports from New Zealand's Coromandel ranges describe a tall, hairy wildman said to haunt the rugged forest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edward%20Tyson%2C%20Orang-Outang%20Wellcome%20L0028397.jpg?width=800"},{"name":"Burrunjor","rarity":"uncommon","id":"burrunjor","subtitle":"Cryptid","details":"Reports from Australia's Northern Territory describe a huge, two-legged reptile said to resemble a living theropod.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Australovenator%20TD.png?width=1024"},{"name":"Dingonek","rarity":"uncommon","id":"dingonek","subtitle":"Cryptid","details":"East African reports describe a walrus-tusked, scaly river beast said to lurk in forest waterways of Kenya.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dingonek.png?width=450"},{"name":"Almasty","rarity":"uncommon","id":"almasty","subtitle":"Cryptid","details":"Reports from Russia's Caucasus region describe a large, hairy wildman long woven into local folklore and sightings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BrehmsTierleben15.jpg?width=1024"},{"name":"Inkanyamba","rarity":"uncommon","id":"inkanyamba","subtitle":"Cryptid","details":"Zulu traditions and reports from South Africa's Howick Falls describe a giant, eel-like serpent with a horse-like head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anguilla%20mossambica.jpg?width=1024"},{"name":"Emela-ntouka","rarity":"uncommon","id":"emela-ntouka","subtitle":"Cryptid","details":"Reports from the Congo's Likouala swamps describe a horned, elephant-sized beast whose name is said to mean 'killer of elephants'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Emela-ntouka.png?width=450"},{"name":"Japanese Wolf","rarity":"uncommon","id":"japanese-wolf","subtitle":"Cryptid","details":"Japan's Honshu wolf was declared extinct in 1905, yet sighting reports from remote mountain forests have continued.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Honshu-wolf3.jpg?width=1024"},{"name":"Dobhar-chú","rarity":"uncommon","id":"dobhar-chu","subtitle":"Cryptid","details":"Irish tradition tells of a huge, otter-like 'hound of the deep' said to haunt lakes, with an old gravestone telling its tale.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dobhar-chu%20encounter.jpg?width=1024"},{"name":"J'ba Fofi","rarity":"uncommon","id":"jba-fofi","subtitle":"Cryptid","details":"Reports from the Congo describe an enormous spider, its name said to mean 'giant spider', lurking in forest-floor burrows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Goliath%20birdeater%20-%20Ara%C3%B1a%20mona%20%28Theraphosa%20blondi%29%20%2814924364629%29.jpg?width=1024"},{"name":"Queensland Tiger","rarity":"uncommon","id":"queensland-tiger","subtitle":"Cryptid","details":"Reports from Queensland, Australia describe a striped, cat-like marsupial predator said to survive in remote ranges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thylacoleo%20BW.jpg?width=1024"},{"name":"Waitoreke","rarity":"uncommon","id":"waitoreke","subtitle":"Cryptid","details":"Reports since the 1860s describe an otter-like mammal in New Zealand's South Island, where no native otters exist.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/European%20otter%2002.jpg?width=1024"},{"name":"Storsjöodjuret","rarity":"uncommon","id":"storsjoodjuret","subtitle":"Cryptid","details":"Sightings reported since 1635 describe a serpent-like creature in Sweden's Lake Storsjön, subject of hundreds of accounts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Draak%20%C3%96stersund%2022jul2006.jpg?width=1024"},{"name":"Calydonian Boar","rarity":"uncommon","id":"calydonian-boar","subtitle":"Monster","details":"In Greek myth Artemis sent the Calydonian Boar to ravage Calydon, and heroes gathered from all Greece to hunt it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peter%20Paul%20Rubens%20-%20The%20Calydonian%20Boar%20Hunt%20-%20Google%20Art%20Project.jpg?width=1024"},{"name":"Erymanthian Boar","rarity":"uncommon","id":"erymanthian-boar","subtitle":"Monster","details":"In Greek myth Heracles, for his fourth labour, chased the Erymanthian Boar through deep snow and captured it alive.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Herakles%20Eurystheus%20boar%20Louvre%20F202.jpg?width=1024"},{"name":"Cretan Bull","rarity":"uncommon","id":"cretan-bull","subtitle":"Mythical Creature","details":"In Greek myth the Cretan Bull, a magnificent fire-snorting bull, was captured by Heracles as his seventh labour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mosaico%20Trabajos%20H%C3%A9rcules%20%28M.A.N.%20Madrid%29%2007.jpg?width=1024"},{"name":"Stymphalian Birds","rarity":"uncommon","id":"stymphalian-birds","subtitle":"Monster","details":"In Greek myth the Stymphalian Birds were man-eating birds with bronze beaks and feathers, scattered by Heracles' rattle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mosaico%20de%20los%20trabajos%20de%20H%C3%A9rcules%2C%20Museo%20Arqueol%C3%B3gico%20Nacional%2C%20Madrid%2C%20Espa%C3%B1a%2C%202016%2004.jpg?width=800"},{"name":"Orthrus","rarity":"uncommon","id":"orthrus","subtitle":"Monster","details":"In Greek myth Orthrus was a two-headed hound, brother of Cerberus, who guarded the red cattle of Geryon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orthos%20Staatliche%20Antikensammlungen%202620.jpg?width=1024"},{"name":"Argus","rarity":"uncommon","id":"argus","subtitle":"Monster","details":"In Greek myth Argus Panoptes, the all-seeing giant, bore eyes all over his body and guarded Io at Hera's command.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peter%20Paul%20Rubens%20-%20Juno%20and%20Argus%20-%20WGA20280.jpg?width=1024"},{"name":"Amphisbaena","rarity":"uncommon","id":"amphisbaena","subtitle":"Monster","details":"Greek writers told of the amphisbaena, a serpent with a head at each end, able to roll in either direction.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/amphisbaena.webp"},{"name":"Catoblepas","rarity":"uncommon","id":"catoblepas","subtitle":"Mythical Creature","details":"Greek and Roman writers described the catoblepas, a heavy-headed beast of Ethiopia whose gaze was said to be deadly.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/catoblepas.webp"},{"name":"Bonnacon","rarity":"uncommon","id":"bonnacon","subtitle":"Mythical Creature","details":"Medieval bestiaries described the bonnacon, a bull-like beast that defended itself by flinging burning dung at hunters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bonnacon.jpg?width=1024"},{"name":"Yale","rarity":"uncommon","id":"yale","subtitle":"Mythical Creature","details":"Medieval bestiaries described the yale, a horse-sized beast whose great horns could swivel to face any attacker.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/yale.webp"},{"name":"Leucrocota","rarity":"uncommon","id":"leucrocota","subtitle":"Mythical Creature","details":"Roman writers described the leucrocota, a swift hybrid beast of India said to mimic the human voice to lure prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morgan%20M.81%2C%20f.047v-leucrota.jpg?width=1024"},{"name":"Cacus","rarity":"uncommon","id":"cacus","subtitle":"Monster","details":"Roman myth told of Cacus, a fire-breathing giant who stole the cattle of Hercules and hid them in his cave on the Aventine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hercule%20et%20Cacus%20Bandinelli%20Florence%20Signoria.jpg?width=1024"},{"name":"Hippocamp","rarity":"uncommon","id":"hippocamp","subtitle":"Mythical Creature","details":"In Greek myth hippocamps, part horse and part fish, drew Poseidon's chariot through the waves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mosaic%20with%20Hippocamp%2C%20a%20mythological%20creature%20with%20hybrid%20body%2C%20half%20horse%20and%20half%20fish%2C%20from%20S%C3%A3o%20Sebasti%C3%A3o%20do%20Freixo%2C%20National%20Archaeology%20Museum%20of%20Lisbon%2C%20Portugal%20%2813188929355%29.jpg?width=1024"},{"name":"Hippogriff","rarity":"uncommon","id":"hippogriff","subtitle":"Mythical Creature","details":"Italian romance gave the hippogriff an eagle's front and a horse's body, a flying steed ridden by knights and wizards.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roger%20d%C3%A9livrant%20Ang%C3%A9lique%20by%20Louis-%C3%89douard%20Rioult.jpg?width=1024"},{"name":"Lamia","rarity":"uncommon","id":"lamia","subtitle":"Monster","details":"In Greek myth Lamia became a child-devouring monster, and her name was used for a class of seductive serpent-women.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Draper-Lamia.jpg?width=1024"},{"name":"Nessus","rarity":"uncommon","id":"nessus","subtitle":"Mythical Creature","details":"In Greek myth Nessus was a centaur whose blood, smeared on a shirt by his dying trick, later brought Heracles to his death.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Group%20of%20Hercules%20slaying%20the%20Centaur%20Nessus-Uffizi%20Gallery.jpg?width=1024"},{"name":"Ceryneian Hind","rarity":"uncommon","id":"ceryneian-hind","subtitle":"Mythical Creature","details":"In Greek myth the Ceryneian Hind, sacred to Artemis, had golden antlers and bronze hooves and outran every hunter but Heracles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Herakles%20hind%20BM%20B231.jpg?width=1024"},{"name":"Chrysomallos","rarity":"uncommon","id":"chrysomallos","subtitle":"Mythical Creature","details":"In Greek myth Chrysomallos was the flying, golden-fleeced ram whose fleece Jason and the Argonauts later sailed to win.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fresco%20depicting%20Phrixus%20and%20Helle%20attempting%20to%20flee%20their%20hate-filled%20stepmother%20by%20crossing%20the%20sea%20between%20Europe%20and%20Asia%20on%20a%20flying%20golden%20ram%2C%20Exhibition%20Medea%27s%20Love%20and%20the%20Hunt%20for%20the%20Golden%20Fleece%20%282018-2019%29%202.jpg?width=800"},{"name":"Chiron","rarity":"uncommon","id":"chiron","subtitle":"Mythical Creature","details":"In Greek myth Chiron, wisest and gentlest of the centaurs, taught heroes such as Achilles in his cave on Mount Pelion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pompeo%20Batoni%20-%20Achilles%20and%20the%20Centaur%20Chiron%20-%20WGA1498.jpg?width=1024"},{"name":"Python","rarity":"uncommon","id":"python","subtitle":"Monster","details":"In Greek myth Python, the great serpent of Delphi, guarded the oracle until the young god Apollo slew it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leto%20with%20Artemis%20%26%20Apollo%20Escaping%20from%20Python%2C%20Greek%2C%204-3rd%20Cent%20BC%20%2810451424666%29.jpg?width=1024"},{"name":"Colchian Dragon","rarity":"uncommon","id":"colchian-dragon","subtitle":"Monster","details":"In Greek myth the sleepless Colchian Dragon guarded the Golden Fleece until Medea charmed it to sleep for Jason.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salvator%20Rosa%20-%20Jason%20Bewitching%20the%20Dragon%20-%20NMH%20Anck%20400%20-%20Nationalmuseum.jpg?width=1024"},{"name":"Nekomata","rarity":"uncommon","id":"nekomata","subtitle":"Yokai","details":"In Japanese folklore, a cat that lives long enough may become a nekomata, its tail splitting in two as it gains eerie powers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suushi_Nekomata.jpg?width=1024"},{"name":"Bakeneko","rarity":"uncommon","id":"bakeneko","subtitle":"Yokai","details":"In Japanese folklore, the bakeneko is a transformed cat that can walk upright, speak, and even take the place of its owner.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Buson_Bakeneko.jpg?width=1024"},{"name":"Rokurokubi","rarity":"uncommon","id":"rokurokubi","subtitle":"Yokai","details":"In Japanese folklore, the rokurokubi appears human by day, but at night her neck stretches to impossible lengths as she wanders.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/22.Nukekubi.jpg?width=1024"},{"name":"Baku","rarity":"uncommon","id":"baku","subtitle":"Yokai","details":"In Japanese folklore, the baku is a chimera with an elephant's trunk that is said to devour bad dreams when called upon at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baku%20by%20Katsushika%20Hokusai.jpg?width=1024"},{"name":"Dokkaebi","rarity":"uncommon","id":"dokkaebi","subtitle":"Mythical Creature","details":"Korean folklore tells of dokkaebi, mischievous goblin spirits formed from old objects, fond of wrestling, tricks, and sudden gifts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%EC%82%B0%EC%88%98%EA%B7%80%EB%AC%B8%EC%A0%84.jpg?width=800"},{"name":"Haetae","rarity":"uncommon","id":"haetae","subtitle":"Mythical Creature","details":"Korean tradition honors the haetae, a unicorn-lion guardian said to judge right from wrong and protect against fire and injustice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Haetae%20In%20Gyeongbokgung%20Palace.JPG?width=1024"},{"name":"Shisa","rarity":"uncommon","id":"shisa","subtitle":"Mythical Creature","details":"In Okinawan tradition, shisa are lion-dog guardians set on roofs and gates, one mouth open to ward off evil, the other closed to keep good in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tomori_Stone_Lion_202006_01.jpg?width=1024"},{"name":"Foo Dog","rarity":"uncommon","id":"foo-dog","subtitle":"Mythical Creature","details":"Chinese tradition places guardian lions, called foo dogs in the West, in pairs before gates to protect the homes and temples behind them.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Transmongolie-660_%2827643744552%29.jpg?width=1024"},{"name":"Taotie","rarity":"uncommon","id":"taotie","subtitle":"Mythical Creature","details":"Chinese myth names the taotie, a ravenous beast whose face was cast onto ancient bronze vessels as a warning against greed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bin_Li.jpg?width=1024"},{"name":"Hundun","rarity":"uncommon","id":"hundun","subtitle":"Mythical Creature","details":"Chinese myth tells of Hundun, the faceless embodiment of primordial chaos, a round being with wings but no eyes, ears, or mouth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hundun.JPG?width=1024"},{"name":"Yaksha","rarity":"uncommon","id":"yaksha","subtitle":"Mythical Creature","details":"In Hindu and Buddhist tradition, yakshas are nature spirits who guard forests, waters, and hidden treasures beneath the earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yaksha_Manibhadra_-_Parkham_Mathura_circa_150_BCE.jpg?width=1024"},{"name":"Makara","rarity":"uncommon","id":"makara","subtitle":"Mythical Creature","details":"In Hindu tradition, the makara is a sea creature part fish, part beast, carved on temple gateways as a guardian of thresholds and waters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Makara_face_at_Konark_temple_01.jpg?width=1024"},{"name":"Airavata","rarity":"uncommon","id":"airavata","subtitle":"Mythical Creature","details":"In Hindu tradition, Airavata is the great white elephant who carries the god Indra and is said to have risen from the churning ocean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Indradeva.jpg?width=1024"},{"name":"Kamadhenu","rarity":"uncommon","id":"kamadhenu","subtitle":"Mythical Creature","details":"In Hindu tradition, Kamadhenu is the divine cow of plenty, said to grant wishes and provide all that her keeper could need.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kamadhenu%2C_the_Wish-Granting_Cow%2C_South_India_possibly_Karnataka%2C_15th_to_17th_century_-_Nelson-Atkins_Museum_of_Art_-_DSC09156.JPG?width=1024"},{"name":"Aswang","rarity":"uncommon","id":"aswang","subtitle":"Mythical Creature","details":"Filipino folklore tells of the aswang, a shape-shifting night creature feared for slipping through villages after dark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aswang%2C_common_form.jpg?width=1024"},{"name":"Manananggal","rarity":"uncommon","id":"manananggal","subtitle":"Mythical Creature","details":"Filipino folklore tells of the manananggal, a woman whose upper body is said to tear free at night and fly on bat-like wings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manananggal.jpg?width=1024"},{"name":"Tikbalang","rarity":"uncommon","id":"tikbalang","subtitle":"Mythical Creature","details":"Filipino folklore tells of the tikbalang, a tall being with a horse's head on a human body that leads travelers astray in the wilds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tikbalang_The_Philippine_Demon_Horse_Commons.jpg?width=800"},{"name":"Kamaitachi","rarity":"uncommon","id":"kamaitachi","subtitle":"Yokai","details":"In Japanese folklore, kamaitachi are lightning-fast weasels riding whirlwinds, said to slash passersby with sickle-sharp claws.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienKamaitachi.jpg?width=1024"},{"name":"Light Elves","rarity":"uncommon","id":"light-elves","subtitle":"Mythical Creature","details":"In Norse myth, the fair Álfar of Álfheim, brighter than the sun in their beauty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rackham%20elves.jpg?width=1024"},{"name":"Dwarves","rarity":"uncommon","id":"dwarves","subtitle":"Mythical Creature","details":"In Norse myth, the master smiths of Svartálfaheim who forged the gods' greatest treasures.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Two%20V%C3%B6lusp%C3%A1%20Dwarves%20by%20Fr%C3%B8lich.jpg?width=1024"},{"name":"Trolls","rarity":"uncommon","id":"trolls","subtitle":"Mythical Creature","details":"Norwegian folklore tells of the forest giants turned to stone by the morning sun.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/John%20Bauer%201915.jpg?width=800"},{"name":"Fire Giant","rarity":"uncommon","id":"fire-giant","subtitle":"Giant","details":"In Norse myth, the flaming giants of Muspelheim who burn the world at Ragnarök.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20giant%20with%20the%20flaming%20sword%20by%20Dollman.jpg?width=800"},{"name":"Ratatoskr","rarity":"uncommon","id":"ratatoskr","subtitle":"Mythical Creature","details":"In Norse myth, the squirrel who runs up and down Yggdrasil carrying insults between eagle and dragon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AM%20738%204to%20Ratatoskr.png?width=1024"},{"name":"Gullinbursti","rarity":"uncommon","id":"gullinbursti","subtitle":"Mythical Creature","details":"In Norse myth, the golden-bristled boar forged by dwarves that pulls Freyr's chariot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20third%20gift%20%E2%80%94%20an%20enormous%20hammer%20by%20Elmer%20Boyd%20Smith.jpg?width=1024"},{"name":"Tanngrisnir & Tanngnjóstr","rarity":"uncommon","id":"tanngrisnir-tanngnjostr","subtitle":"Mythical Creature","details":"In Norse myth, Thor's two goats who pull his chariot and are eaten and reborn each night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thor%20(1832)%20from%20Die%20Helden%20und%20G%C3%B6tter%20des%20Nordens%2C%20oder%20Das%20Buch%20der%20sagen.jpg?width=1024"},{"name":"Eikþyrnir","rarity":"uncommon","id":"eikyrnir","subtitle":"Mythical Creature","details":"In Norse myth, the stag atop Valhalla whose antlers drip the rivers of the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AM%20738%204to%20Eikthyrnir%20Heidrun.jpg?width=1024"},{"name":"Heiðrún","rarity":"uncommon","id":"heirun","subtitle":"Mythical Creature","details":"In Norse myth, the goat on Valhalla's roof whose udders give mead for the fallen warriors.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/heidrun.webp"},{"name":"Landvættir","rarity":"uncommon","id":"landvttir","subtitle":"Spirit","details":"Icelandic folklore tells of the land spirits who guard the island and must be honored at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coat%20of%20arms%20of%20Iceland.svg?width=1024"},{"name":"Clurichaun","rarity":"uncommon","id":"clurichaun","subtitle":"Mythical Creature","details":"Irish folklore tells of the solitary fairy who haunts wine cellars and guards hidden treasure.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Celtic%20Fairy%20Tales-1892-048-1.jpg?width=1024"},{"name":"Geri & Freki","rarity":"uncommon","id":"geri-freki","subtitle":"Mythical Creature","details":"In Norse myth, Odin's two wolves who feast at his table while he drinks only wine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Odin%20(Manual%20of%20Mythology).jpg?width=1024"},{"name":"Leanan Sídhe","rarity":"uncommon","id":"leanan-sidhe","subtitle":"Spirit","details":"Irish folklore tells of the fairy lover who inspires poets, then withers them with her kiss.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dicksee%20Frank%2C%20La%20Belle%20Dame%20Sans%20Merci.jpg?width=1024"},{"name":"Cape Ann Sea Serpent","rarity":"uncommon","id":"cape-ann-sea-serpent","subtitle":"Sea Monster","details":"In 1639, colonists at Cape Ann reported a great sea serpent coiling on a rock by the shore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20serpent%20Cape%20Ann%201639.jpg?width=1024"},{"name":"Great Sea Serpent","rarity":"uncommon","id":"great-sea-serpent","subtitle":"Sea Monster","details":"For centuries, ship captains reported a great unknown serpent in the open ocean, never captured or explained.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20serpent%20from%20Hart%20Nautical%20Collections.jpg?width=1024"},{"name":"Daedalus Sea Serpent","rarity":"uncommon","id":"daedalus-sea-serpent","subtitle":"Sea Monster","details":"In 1848, officers of HMS Daedalus reported a huge serpent-like creature swimming past their ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMS%20Daedalus%20with%20sea%20serpent.jpg?width=1024"},{"name":"Firebird","rarity":"uncommon","id":"firebird","subtitle":"Mythical Creature","details":"In Slavic fairy tales, the Firebird is a glowing magical bird whose feathers light up the night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Firebird.jpg?width=1024"},{"name":"Pouakai","rarity":"uncommon","id":"pouakai","subtitle":"Mythical Creature","details":"Maori legend told of Pouakai, a giant eagle said to swoop down and carry off people.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant%20Haasts%20eagle%20attacking%20New%20Zealand%20moa.jpg?width=1024"},{"name":"Senmurv","rarity":"uncommon","id":"senmurv","subtitle":"Mythical Creature","details":"In Persian tradition, the Senmurv is a winged dog-like creature that roosts in the Tree of All Seeds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gilded%20silver%20plate%20depicting%20a%20simorgh%20with%20a%20leaf%20hanging%20from%20its%20mouth%2C%20Sasanian%20style%2C%20Early%20Islamic%20period%2C%207th-8th%20century%20-%20British%20Museum%201922%2C0308.1.jpg?width=1024"},{"name":"Alicanto","rarity":"uncommon","id":"alicanto","subtitle":"Mythical Creature","details":"Chilean mining folklore tells of the Alicanto, a glowing bird whose wings shine with gold or silver.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alicanto.jpg?width=1024"},{"name":"Steller's Sea Ape","rarity":"uncommon","id":"stellers-sea-ape","subtitle":"Sea Monster","details":"In 1741, naturalist Georg Steller reported a strange sea creature with a dog-like head off Alaska.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Conrad%20Gessner%20-%20Simia%20marina.jpg?width=1024"},{"name":"Dakuwaqa","rarity":"uncommon","id":"dakuwaqa","subtitle":"Sea Monster","details":"In Fijian tradition, Dakuwaqa is a shark god, protector of fishermen and guardian of the reefs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dakuwaqa-71.1969.51.25-DSC00435-black.jpg?width=1024"},{"name":"Jasconius","rarity":"uncommon","id":"jasconius","subtitle":"Sea Monster","details":"In the Irish voyage tale of Saint Brendan, Jasconius is a giant fish whose back was mistaken for an island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saint%20brendan%20german%20manuscript.jpg?width=1024"},{"name":"Vucub Caquix","rarity":"uncommon","id":"vucub-caquix","subtitle":"Mythical Creature","details":"In Maya tradition, Vucub Caquix is a vain bird demon who falsely claimed to be the sun and moon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Izapa%20stela25.jpg?width=1024"},{"name":"Giant Squid","rarity":"uncommon","id":"giant-squid","subtitle":"Sea Monster","details":"Long dismissed as sailors' fiction, the giant squid is a real deep-sea animal with eyes the size of plates.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20000%20squid%20holding%20sailor.jpg?width=500"},{"name":"Hydrarchos","rarity":"uncommon","id":"hydrarchos","subtitle":"Sea Monster","details":"In 1845, Albert Koch exhibited a huge fossil skeleton in New York, claiming it was a giant sea serpent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hydrarchos.jpg?width=1024"},{"name":"Bermuda Sea Serpent","rarity":"uncommon","id":"bermuda-sea-serpent","subtitle":"Sea Monster","details":"In 1860, a long serpent-like carcass found on Bermuda was reported as a sea serpent; it was likely an oarfish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant%20oarfish%20bermuda%20beach%201860.jpg?width=1024"},{"name":"Squonk","rarity":"common","id":"squonk","subtitle":"Cryptid","details":"Pennsylvania lumber lore tells of a wart-covered squonk so ashamed of its looks that it is said to dissolve into tears.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Squonk.jpg?width=1024"},{"name":"Cactus Cat","rarity":"common","id":"cactus-cat","subtitle":"Cryptid","details":"Southwestern desert lumber lore tells of a cat that slashes cacti with the spines on its legs and drinks the fermented juice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cactus%20cat.jpg?width=1024"},{"name":"Fur-Bearing Trout","rarity":"common","id":"fur-bearing-trout","subtitle":"Cryptid","details":"Tall tales of the northern lakes tell of trout grown furred against the cold, mounted as trophies in fishing camps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fur%20bearing%20trout.%20Very%20rare.%20%283793949065%29.jpg?width=1024"},{"name":"Hoop Snake","rarity":"common","id":"hoop-snake","subtitle":"Cryptid","details":"Frontier tales tell of a snake that bites its own tail and rolls along like a hoop, faster than a horse can run.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoop%20snake.jpg?width=1024"},{"name":"Sidehill Gouger","rarity":"common","id":"sidehill-gouger","subtitle":"Cryptid","details":"Mountain lumber lore tells of a beast with legs longer on one side, built for grazing steep hillsides in one direction.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sidehill-Gouger.jpg?width=1024"},{"name":"Splintercat","rarity":"common","id":"splintercat","subtitle":"Cryptid","details":"Pacific Northwest lumber lore tells of a cat that charges trees headfirst, splintering the trunks to reach what is inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Splintercat.png?width=1024"},{"name":"Hidebehind","rarity":"common","id":"hidebehind","subtitle":"Cryptid","details":"Northern lumber lore tells of a tall beast that always stands behind a tree when watched, and behind the watcher when not.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hidebehind.jpg?width=1024"},{"name":"Axhandle Hound","rarity":"common","id":"axhandle-hound","subtitle":"Cryptid","details":"Lumbercamp lore tells of a dog with an axe-shaped head, said to roam the camps eating the handles of unattended axes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Axhandle%20hound.jpg?width=1024"},{"name":"Ball-Tailed Cat","rarity":"common","id":"ball-tailed-cat","subtitle":"Cryptid","details":"Lumber lore tells of a mountain cat with a heavy ball on the end of its tail, dropped on prey from the branches above.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ball%20tailed%20cat.jpg?width=1024"},{"name":"Agropelter","rarity":"common","id":"agropelter","subtitle":"Cryptid","details":"Northern lumber lore tells of a spiteful tree-dweller that hurls dead branches down on the loggers passing below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agropelter.jpg?width=1024"},{"name":"Tripodero","rarity":"common","id":"tripodero","subtitle":"Cryptid","details":"California chaparral lore tells of a long-legged beast that collapses its legs like a telescope to slip through the brush.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tripodero.jpg?width=1024"},{"name":"Whirling Whimpus","rarity":"common","id":"whirling-whimpus","subtitle":"Cryptid","details":"Lumber lore tells of a gorilla-like whimpus that spins on one foot until it is invisible, then snatches its prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Whimpus.jpg?width=1024"},{"name":"Roperite","rarity":"common","id":"roperite","subtitle":"Cryptid","details":"Sierra foothill lore tells of a beaked, flightless bird that lassos jackrabbits with its rope-like beak at a run.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roperite.jpg?width=1024"},{"name":"Goofus Bird","rarity":"common","id":"goofus-bird","subtitle":"Cryptid","details":"Lumber lore tells of the goofus bird, or fillamaloo, which flies backward because it only wants to see where it has been.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fillamaloo.jpg?width=1024"},{"name":"Rumtifusel","rarity":"common","id":"rumtifusel","subtitle":"Cryptid","details":"Lumber lore tells of a thin, fur-draped beast that hangs on a tree like a coonskin coat until its prey wanders beneath.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rumtifusel.jpg?width=1024"},{"name":"Santer","rarity":"common","id":"santer","subtitle":"Cryptid","details":"North Carolina lore tells of the santer, a long-tailed wild cat said to knock its victims senseless with a swipe of its tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Santer.jpg?width=1024"},{"name":"Tote-Road Shagamaw","rarity":"common","id":"tote-road-shagamaw","subtitle":"Cryptid","details":"Maine lumber lore tells of the shagamaw, whose tracks change from bear to man along the tote-roads, baffling trackers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fearsome%20Creatures%20of%20the%20Lumberwoods%2C%20with%20a%20Few%20Desert%20and%20Mountain%20Beasts%20%28page%2028%20crop%29.jpg?width=1024"},{"name":"Leprocaun","rarity":"common","id":"leprocaun","subtitle":"Cryptid","details":"Upper Canada lumber lore tells of the leprocaun, a mischievous devil-monkey blamed for log jams and vanishing tools.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fearsome%20Creatures%20of%20the%20Lumberwoods%2C%20with%20a%20Few%20Desert%20and%20Mountain%20Beasts%20%28page%2022%20crop%29.jpg?width=1024"},{"name":"Funeral Mountain Terrashot","rarity":"common","id":"funeral-mountain-terrashot","subtitle":"Cryptid","details":"Death Valley lore tells of the terrashot of the Funeral Mountains, a desert beast said to burst from the earth itself.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fearsome%20Creatures%20of%20the%20Lumberwoods%2C%20with%20a%20Few%20Desert%20and%20Mountain%20Beasts%20%28page%2024%20crop%29.jpg?width=1024"},{"name":"Wapaloosie","rarity":"common","id":"wapaloosie","subtitle":"Cryptid","details":"Pacific Coast lumber lore tells of a spiny, caterpillar-like climber that inches up the tallest firs to feed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fearsome%20Creatures%20of%20the%20Lumberwoods%2C%20with%20a%20Few%20Desert%20and%20Mountain%20Beasts%20%28page%2030%20crop%29.jpg?width=1024"},{"name":"Dungavon Hooter","rarity":"common","id":"dungavon-hooter","subtitle":"Cryptid","details":"New Brunswick lumber lore tells of the Dungavon hooter, a hollow-log dweller named for its river and its eerie cry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dungavenhooter.jpg?width=1024"},{"name":"Silver Cat","rarity":"common","id":"silver-cat","subtitle":"Cryptid","details":"Lumber lore tells of a great silver cat that dangles its glowing, knobbed tail from a branch to lure prey within reach.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Silver%20cat.jpg?width=1024"},{"name":"Treesqueak","rarity":"common","id":"treesqueak","subtitle":"Cryptid","details":"Northern lumber lore tells of the treesqueak, a small beast that clings to birch bark and is heard more often than seen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Treesqueak.jpg?width=1024"},{"name":"Dingmaul","rarity":"common","id":"dingmaul","subtitle":"Cryptid","details":"New England lumber lore tells of the dingmaul, a great cat-like beast with a long tail ending in a spiked ball.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dingmaul.jpg?width=1024"},{"name":"Come-at-a-Body","rarity":"common","id":"come-at-a-body","subtitle":"Cryptid","details":"Lumber lore tells of the come-at-a-body, a small, fierce beast that charges lumberjacks head-on, all teeth and temper.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Come%20at%20a%20body.jpg?width=1024"},{"name":"Squink","rarity":"common","id":"squink","subtitle":"Cryptid","details":"Pacific Northwest lore tells of the Columbia River sand squink, a long-eared burrower of the riverbanks and dunes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Squink.jpg?width=1024"},{"name":"Whiffenpoof","rarity":"common","id":"whiffenpoof","subtitle":"Cryptid","details":"Anglers' tall tales tell of the whiffenpoof, a colossal fish of the northern lakes that no hook has ever held.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Whiffenpoof.jpg?width=1024"},{"name":"Luferlang","rarity":"common","id":"luferlang","subtitle":"Cryptid","details":"Lumber lore tells of the luferlang, whose horn is said to cure any poison, and whose temper cures trespassers instead.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Luferlang.jpg?width=1024"},{"name":"Kasai Rex","rarity":"common","id":"kasai-rex","subtitle":"Cryptid","details":"Reports from the Congo's Kasai River valley in 1932 described a huge, two-legged predator said to resemble a tyrannosaur.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Triceratops%20and%20Tyrannosaurus%20by%20Knight.jpg?width=1024"},{"name":"Shug Monkey","rarity":"common","id":"shug-monkey","subtitle":"Cryptid","details":"Reports from Rendlesham Forest, England describe a creature said to blend a monkey's shape with a dog's size and gait.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mantiger%201763.jpg?width=1024"},{"name":"Brosno Dragon","rarity":"common","id":"brosno-dragon","subtitle":"Cryptid","details":"Reports from Russia's Lake Brosno describe a huge, dragon-like creature said to surface near fishing boats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brontoicon.jpg?width=1024"},{"name":"Moa","rarity":"common","id":"moa","subtitle":"Cryptid","details":"New Zealand's giant moa died out centuries ago, yet reported sightings of huge flightless birds persist in the South Island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MA%20I239180%20TePapa%20Moa-skeleton%20full.jpg?width=1024"},{"name":"Lariosauro","rarity":"common","id":"lariosauro","subtitle":"Cryptid","details":"Reports since 1946 describe a small, plesiosaur-like reptile in Italy's Lake Como, named for the fossil Lariosaurus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lariosaurus%20valceresii%20%28CMISN500%29.jpg?width=1024"},{"name":"Javan Tiger","rarity":"common","id":"javan-tiger","subtitle":"Cryptid","details":"Java's tiger was declared extinct in the 1970s, yet reported sightings in remote forests have never fully stopped.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panthera%20tigris%20sondaica%2001.jpg?width=800"},{"name":"Bali Tiger","rarity":"common","id":"bali-tiger","subtitle":"Cryptid","details":"Bali's tiger vanished by the 1940s, but islanders have reported striped, cat-like figures in remote forests ever since.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bali%20tiger%20zanveld.jpg?width=1024"},{"name":"Yacumama","rarity":"common","id":"yacumama","subtitle":"Cryptid","details":"Amazonian tradition in Peru tells of a colossal water serpent said to guard rivers and swallow boats whole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LA%20YACUMAMA%20Y%20EL%20PESCADOR%20MEZQUINO.jpg?width=1024"},{"name":"Sucuriju","rarity":"common","id":"sucuriju","subtitle":"Cryptid","details":"Reports from Brazil describe a truly gigantic anaconda, far larger than any measured, said to crush cattle at riversides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sucuri%20verde.jpg?width=1024"},{"name":"Batutut","rarity":"common","id":"batutut","subtitle":"Cryptid","details":"Reports from Vietnam, Laos and Borneo describe a shy, ape-like 'forest person' said to leave human-like footprints.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/273170211%20280319627385788%208107247424865713931n.capcha.jpg?width=1024"},{"name":"Orang Mawas","rarity":"common","id":"orang-mawas","subtitle":"Cryptid","details":"Reports from Malaysia's Johor forests describe a large, black-furred, ape-like figure said to walk upright.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Natural%20History%20with%20Anecdotes%20%28Miles%201895%29%20-%20Orangutan%20illustration.jpg?width=1024"},{"name":"Blue Mountains Panther","rarity":"common","id":"blue-mountains-panther","subtitle":"Cryptid","details":"Reports from Australia's Blue Mountains describe a large black panther said to prowl bushland west of Sydney.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20black%20panther%20%28melanistic%20african%20leopard%29%2C%20yawning.jpg?width=1024"},{"name":"Beast of Exmoor","rarity":"common","id":"beast-of-exmoor","subtitle":"Cryptid","details":"Reports since the 1970s describe a large, dark big cat said to stalk livestock across Devon's Exmoor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Puma%201.JPG?width=1024"},{"name":"Mamlambo","rarity":"common","id":"mamlambo","subtitle":"Cryptid","details":"Zulu tradition in South Africa tells of a river serpent with a horse-like head said to haunt the Mzintlava River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anguilla%20marmorata%20Stuffed%20specimen.jpg?width=1024"},{"name":"Mbielu-Mbielu-Mbielu","rarity":"common","id":"mbielu-mbielu-mbielu","subtitle":"Cryptid","details":"Reports from the Congo describe a plated, fin-backed reptile said to bask in rivers, seen in only a handful of accounts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mbielu-mbielu-mbielu.png?width=800"},{"name":"Nguma-monene","rarity":"common","id":"nguma-monene","subtitle":"Cryptid","details":"Reports from Cameroon describe a huge, frill-backed, serpent-like reptile said to glide through remote rivers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nguma-monene.png?width=800"},{"name":"Trunko","rarity":"common","id":"trunko","subtitle":"Cryptid","details":"In 1924, a white, furry, trunked carcass washed ashore at Margate, South Africa, and was nicknamed Trunko.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/trunko.webp"},{"name":"Adjule","rarity":"common","id":"adjule","subtitle":"Cryptid","details":"Reports from North Africa describe a dog-like beast, also called the Kelb-el-khela, said to roam remote desert wadis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adjule.jpg?width=1024"},{"name":"Popobawa","rarity":"common","id":"popobawa","subtitle":"Cryptid","details":"Tanzanian reports, notably on Pemba Island in 1995, describe a shape-shifting, bat-winged being that panicked villages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pteropus%20alecto%20on%20a%20branch.jpg?width=1024"},{"name":"Beast of Dean","rarity":"common","id":"beast-of-dean","subtitle":"Cryptid","details":"Reports from England's Forest of Dean describe a boar of enormous size, nicknamed the 'moose pig' by locals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beast%20of%20Dean.jpg?width=1024"},{"name":"Mngwa","rarity":"common","id":"mngwa","subtitle":"Cryptid","details":"Reports from Tanzania describe a huge, grey, striped cat said to be larger and fiercer than any leopard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caracal%20aurata%202.jpg?width=1024"},{"name":"Ennedi Tiger","rarity":"common","id":"ennedi-tiger","subtitle":"Cryptid","details":"Reports from Chad's Ennedi Plateau describe a large, saber-fanged cat said to survive in remote mountain caves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Smilodon%20Knight.jpg?width=1024"},{"name":"Maltese Tiger","rarity":"common","id":"maltese-tiger","subtitle":"Cryptid","details":"Reports from China's Fujian province describe a tiger with bluish-grey fur, nicknamed the Maltese or blue tiger.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue%20tiger.jpg?width=1024"},{"name":"Tatzelwurm","rarity":"common","id":"tatzelwurm","subtitle":"Cryptid","details":"Alpine reports describe a stubby, lizard-like burrower with a cat-like face, said to lurk in the Austrian and Swiss Alps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tatzelwurm%20%28cropped%29.jpg?width=1024"},{"name":"De Loys' Ape","rarity":"common","id":"de-loys-ape","subtitle":"Cryptid","details":"A 1920 photograph from Venezuela claimed to show a large, tailless ape; the image has been debated ever since.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/De%20Loys%27%20Ape.jpg?width=1024"},{"name":"Ahool","rarity":"common","id":"ahool","subtitle":"Cryptid","details":"Reports from Java, Indonesia describe a bat with a wingspan said to exceed three metres, glimpsed over rainforest rivers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mauritian%20flying%20fox%20%28Pteropus%20niger%29%20in%20flight%203.jpg?width=1024"},{"name":"Bergman's Bear","rarity":"common","id":"bergmans-bear","subtitle":"Cryptid","details":"Reports from Russia's Kamchatka Peninsula describe a truly enormous brown bear, far larger than typical, seen by hunters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kamtschatkab%C3%A4r%20Ursus%20arctos%20piscator%201250.jpg?width=1024"},{"name":"Satyr","rarity":"common","id":"satyr","subtitle":"Mythical Creature","details":"In Greek myth satyrs, part man and part goat, roamed woods and hills in the wild retinue of Dionysus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Satyros%20Cdm%20Paris%20DeRidder509.jpg?width=1024"},{"name":"Faun","rarity":"common","id":"faun","subtitle":"Mythical Creature","details":"Roman myth told of fauns, part man and part goat, shy spirits of the countryside and protectors of flocks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Faun%20merse.jpg?width=1024"},{"name":"Triton","rarity":"common","id":"triton","subtitle":"Mythical Creature","details":"In Greek myth Triton, part man and part fish, blew a conch that could raise or calm the waves of the sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Herakles%20Triton%20Met%2006.1021.48.jpg?width=1024"},{"name":"Fury","rarity":"common","id":"fury","subtitle":"Mythical Creature","details":"In Greek myth the Furies, the Erinyes, rose from blood to hunt those guilty of murder and broken oaths.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orestes%20Pursued%20by%20the%20Furies%20by%20William-Adolphe%20Bouguereau%20%281862%29%20-%20Google%20Art%20Project.jpg?width=1024"},{"name":"Graeae","rarity":"common","id":"graeae","subtitle":"Mythical Creature","details":"In Greek myth the Graeae were three ancient sisters who shared one eye and one tooth between them.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edward%20Burne-Jones%20-%20Perseus%20and%20the%20Graiae%2C%201892.jpg?width=1024"},{"name":"Hippalectryon","rarity":"common","id":"hippalectryon","subtitle":"Mythical Creature","details":"In Greek art the hippalectryon joined a horse's front to a cockerel's wings, tail and legs, a playful hybrid steed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Warrior%20hippalectryon%20Louvre%20CA1792.jpg?width=1024"},{"name":"Onocentaur","rarity":"common","id":"onocentaur","subtitle":"Mythical Creature","details":"Medieval bestiaries described the onocentaur, part man and part donkey, as a creature of two conflicting natures.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/onocentaur.webp"},{"name":"Ichthyocentaur","rarity":"common","id":"ichthyocentaur","subtitle":"Mythical Creature","details":"In Greek art ichthyocentaurs joined a man's torso and horse's legs to a fish's tail, and escorted sea processions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ichthyocentaur%2C%20hotel%20Sacher-VIENNA-Dr.%20Murali%20Mohan%20Gurram%20%285%29.jpg?width=1024"},{"name":"Crocotta","rarity":"common","id":"crocotta","subtitle":"Mythical Creature","details":"Greek and Roman writers described the crocotta, a dog-wolf hybrid of Ethiopia said to dig up graves and mimic voices.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crocotta.jpg?width=1024"},{"name":"Jaculus","rarity":"common","id":"jaculus","subtitle":"Monster","details":"Roman writers told of the jaculus, a flying serpent that launched itself from trees onto prey below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jaculus.jpg?width=1024"},{"name":"Arachne","rarity":"common","id":"arachne","subtitle":"Monster","details":"In Greek myth Arachne, a weaver who boasted over Athena, was changed into a spider to weave forever.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pur%2012%20aracne.jpg?width=1024"},{"name":"Laelaps","rarity":"common","id":"laelaps","subtitle":"Mythical Creature","details":"In Greek myth Laelaps was the hound fated never to fail in the chase, set against the fox that could never be caught.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Piero%20di%20cosimo%2C%20morte%20di%20procri%2003.jpg?width=1024"},{"name":"Allocamelus","rarity":"common","id":"allocamelus","subtitle":"Mythical Creature","details":"Early natural histories pictured the allocamelus with a camel's body and a donkey's head, from travellers' reports.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Allocamelus%20from%20Topsell%27s%20The%20History%20of%20Four-footed%20Beasts%20and%20Serpents.jpg?width=1024"},{"name":"Caladrius","rarity":"common","id":"caladrius","subtitle":"Mythical Creature","details":"Medieval bestiaries told of the caladrius, a white bird that faced the sick who would live and turned from those who would die.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caladrius2.jpg?width=1024"},{"name":"Hercinia","rarity":"common","id":"hercinia","subtitle":"Mythical Creature","details":"Medieval writers told of the hercinia, a bird of German forests whose glowing feathers lit the way for travellers at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hercinea%203244.jpg?width=1024"},{"name":"Scitalis","rarity":"common","id":"scitalis","subtitle":"Monster","details":"Medieval bestiaries described the scitalis, a serpent so dazzlingly patterned that prey stopped, charmed, to stare.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scitalis%203244.jpg?width=1024"},{"name":"Myrmecoleon","rarity":"common","id":"myrmecoleon","subtitle":"Mythical Creature","details":"Medieval bestiaries told of the myrmecoleon, part lion and part ant, a creature of two natures that could eat as neither.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Myrmecoleon%201491.jpg?width=1024"},{"name":"Blemmye","rarity":"common","id":"blemmye","subtitle":"Mythical Creature","details":"Ancient and medieval writers placed the Blemmyes, headless men with faces in their chests, at the edges of the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nuremberg%20chronicles%20-%20Strange%20People%20-%20Headless%20%28XIIr%29.jpg?width=1024"},{"name":"Sciapod","rarity":"common","id":"sciapod","subtitle":"Mythical Creature","details":"Greek writers told of the Sciapods, one-legged people of India who shaded themselves with a single enormous foot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nuremberg%20chronicles%20-%20Strange%20People%20-%20Umbrella%20Foot%20%28XIIr%29.jpg?width=1024"},{"name":"Cynocephalus","rarity":"common","id":"cynocephalus","subtitle":"Mythical Creature","details":"Greek writers told of the Cynocephali, dog-headed people said to live beyond India and speak only in barks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alexander%20fighting%20the%20dog-headed%20Cynocephali.jpg?width=1024"},{"name":"Wolpertinger","rarity":"common","id":"wolpertinger","subtitle":"Mythical Creature","details":"Bavarian folklore tells of the Wolpertinger, a small winged, antlered hare said to haunt Alpine forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wolpertinger.jpg?width=1024"},{"name":"Salamander","rarity":"common","id":"salamander","subtitle":"Mythical Creature","details":"Medieval bestiaries held the salamander a creature of fire, able to live unburned in flames and quench them with its cold body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salamandre%203244.jpg?width=1024"},{"name":"Panther","rarity":"common","id":"panther","subtitle":"Mythical Creature","details":"Medieval bestiaries described the panther as a gentle, many-coloured beast whose sweet breath drew every animal but the dragon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AberdeenBestiaryFolio009rPantherDetail.jpg?width=1024"},{"name":"Dipsa","rarity":"common","id":"dipsa","subtitle":"Monster","details":"Roman poets told of the dipsa, a tiny desert serpent whose bite was said to cause a burning, unquenchable thirst.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dipsas%20%28kind%20of%20snake%29%20-%20Der%20naturen%20bloeme%20-%20Jacob%20van%20Maerlant%20-%20KB%20KA%2016%20-%20123v%20b2.jpg?width=1024"},{"name":"Seps","rarity":"common","id":"seps","subtitle":"Monster","details":"Medieval bestiaries described the seps, a small serpent whose venom was said to dissolve flesh and bone alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Seps%20royal%20MS12.jpg?width=1024"},{"name":"Hydrus","rarity":"common","id":"hydrus","subtitle":"Monster","details":"Medieval bestiaries told of the hydrus, a water serpent that let crocodiles swallow it, then burst out alive.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/hydrus.webp"},{"name":"Parandrus","rarity":"common","id":"parandrus","subtitle":"Mythical Creature","details":"Medieval bestiaries described the parandrus, an ox-sized beast of Ethiopia that changed colour to hide, like a chameleon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morgan%20M.81%2C%20f.039r-parandrus.jpg?width=1024"},{"name":"Mares of Diomedes","rarity":"common","id":"mares-of-diomedes","subtitle":"Monster","details":"In Greek myth the man-eating Mares of Diomedes were tamed by Heracles, who fed them their own master.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mosaico%20de%20los%20trabajos%20de%20H%C3%A9rcules%2C%20Museo%20Arqueol%C3%B3gico%20Nacional%2C%20Madrid%2C%20Espa%C3%B1a%2C%202016%2011.jpg?width=800"},{"name":"Geryon","rarity":"common","id":"geryon","subtitle":"Monster","details":"In Greek myth Geryon was a three-bodied giant of the far west whose red cattle Heracles drove away to Greece.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%A9ryon%20%28L%201%29.jpg?width=1024"},{"name":"Krasue","rarity":"common","id":"krasue","subtitle":"Mythical Creature","details":"Thai folklore tells of the krasue, a floating woman's head trailing glowing entrails that drifts through the night in search of food.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/XRF-krasue.jpg?width=1024"},{"name":"Preta","rarity":"common","id":"preta","subtitle":"Mythical Creature","details":"In Buddhist tradition, pretas are hungry ghosts with huge bellies and needle-thin throats, forever craving what they cannot swallow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pyetta_%28hungry_ghosts%29.jpg?width=800"},{"name":"Futakuchi-onna","rarity":"common","id":"futakuchi-onna","subtitle":"Yokai","details":"In Japanese folklore, the futakuchi-onna hides a second, ravenous mouth in the back of her head, fed by hair that moves like serpents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Futakuchi-onna.jpg?width=1024"},{"name":"Yurei","rarity":"common","id":"yurei","subtitle":"Yokai","details":"In Japanese folklore, yurei are ghosts bound to the world by strong emotion, drifting in white burial clothes with long, loose black hair.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/23.Yuurei.jpg?width=1024"},{"name":"Kasa-obake","rarity":"common","id":"kasa-obake","subtitle":"Yokai","details":"In Japanese folklore, the kasa-obake is a forgotten umbrella come to life, hopping on one leg with a single eye and a long, lolling tongue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Enshin_Kasa-obake.jpg?width=1024"},{"name":"Chochin-obake","rarity":"common","id":"chochin-obake","subtitle":"Yokai","details":"In Japanese folklore, the chochin-obake is an old paper lantern come to life, opening one great eye and a wide, toothy grin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shunkosai%20Hokuei%20Obake.jpg?width=1024"},{"name":"Hitotsume-kozo","rarity":"common","id":"hitotsume-kozo","subtitle":"Yokai","details":"In Japanese folklore, the hitotsume-kozo is a small, bald, one-eyed monk-like yokai that startles travelers but rarely does real harm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Masayoshi%20Hitotsume-kozo.jpg?width=1024"},{"name":"Nurikabe","rarity":"common","id":"nurikabe","subtitle":"Yokai","details":"In Japanese folklore, the nurikabe is an invisible wall that blocks night roads; walkers who meet it find no way past until dawn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Torin_Nukaribe.jpg?width=1024"},{"name":"Wanyudo","rarity":"common","id":"wanyudo","subtitle":"Yokai","details":"In Japanese folklore, Wanyudo is a flaming cart wheel bearing a tormented face, said to steal the souls of those who see it roll by.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienWanyudo.jpg?width=1024"},{"name":"Nuppeppo","rarity":"common","id":"nuppeppo","subtitle":"Yokai","details":"In Japanese folklore, the nuppeppo is a shambling lump of flesh with a face hidden in its folds, said to wander temples at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/13.Nuppeppou.jpg?width=1024"},{"name":"Jami","rarity":"common","id":"jami","subtitle":"Yokai","details":"In Japanese folklore, the jami is a wicked spirit of wild mountains and rivers, pictured by Toriyama Sekien prowling among the pines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienJami.jpg?width=1024"},{"name":"Hashihime","rarity":"common","id":"hashihime","subtitle":"Yokai","details":"In Japanese folklore, Hashihime is a jealous woman said to have prayed herself into a demon at Kyoto's Uji Bridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Masasumi_Hashihime.jpg?width=1024"},{"name":"Inugami","rarity":"common","id":"inugami","subtitle":"Yokai","details":"In Japanese folklore, the inugami is a dog spirit kept by certain families, said to protect its masters and curse their enemies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suushi_Inugami.jpg?width=1024"},{"name":"Mokumokuren","rarity":"common","id":"mokumokuren","subtitle":"Yokai","details":"In Japanese folklore, mokumokuren are eyes that peer from torn paper screens in old, neglected houses, watching whoever moves in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienMokumokuren.jpg?width=1024"},{"name":"Nure-onna","rarity":"common","id":"nure-onna","subtitle":"Yokai","details":"In Japanese folklore, the nure-onna is a serpent-bodied woman who haunts rivers and shores, her hair soaked and her gaze deadly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suushi_Nure-onna.jpg?width=1024"},{"name":"Shojo","rarity":"common","id":"shojo","subtitle":"Yokai","details":"In Japanese folklore, shojo are red-haired sea spirits with a legendary love of sake, said to brew a wine that can cure or kill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kansai-after-Hokusai-KatsushikaShins%C5%8DGafu%281890%29-fol26-shojo.jpg?width=1024"},{"name":"Ubume","rarity":"common","id":"ubume","subtitle":"Yokai","details":"In Japanese folklore, an ubume is the ghost of a woman who died in childbirth, said to wander at night cradling her child.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/12.Ubume.jpg?width=1024"},{"name":"Yamauba","rarity":"common","id":"yamauba","subtitle":"Yokai","details":"In Japanese folklore, Yamauba is a wild mountain crone who may shelter lost travelers kindly — or invite them in for a darker purpose.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suushi_Yama-uba.jpg?width=800"},{"name":"Enenra","rarity":"common","id":"enenra","subtitle":"Yokai","details":"In Japanese folklore, the enenra is a being made of smoke and darkness that drifts from bonfires and takes shape only for the pure of heart.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienEnenra.jpg?width=1024"},{"name":"Ushi-oni","rarity":"common","id":"ushi-oni","subtitle":"Yokai","details":"In Japanese folklore, the ushi-oni is a monstrous ox-headed beast said to prowl coasts and mountains, breathing poison on its victims.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/29.Ushioni.jpg?width=1024"},{"name":"Tsurube-otoshi","rarity":"common","id":"tsurube-otoshi","subtitle":"Yokai","details":"In Japanese folklore, the tsurube-otoshi hides in treetops and drops like a falling bucket — or a severed head — onto those below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Genrin%20Tsurube-oroshi.jpg?width=1024"},{"name":"Ittan-momen","rarity":"common","id":"ittan-momen","subtitle":"Yokai","details":"In Japanese folklore, the ittan-momen is a long strip of white cloth that flutters through the night sky, wrapping itself around faces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mitsunobu%20cloth-like%20monster.jpg?width=1024"},{"name":"Otoroshi","rarity":"common","id":"otoroshi","subtitle":"Yokai","details":"In Japanese folklore, the otoroshi is a shaggy, fanged beast that perches atop shrine gates and drops on the impious passing below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienOtoroshi.jpg?width=1024"},{"name":"Satori","rarity":"common","id":"satori","subtitle":"Yokai","details":"In Japanese folklore, the satori is an ape-like mountain creature said to read travelers' thoughts and speak them aloud before they can.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienSatori.jpg?width=1024"},{"name":"Akaname","rarity":"common","id":"akaname","subtitle":"Yokai","details":"In Japanese folklore, the akaname is a small, red yokai said to creep into neglected bathhouses and lick up the grime with its long tongue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienAkaname.jpg?width=1024"},{"name":"Yamabiko","rarity":"common","id":"yamabiko","subtitle":"Yokai","details":"In Japanese folklore, the yamabiko is a mountain spirit whose voice answers shouts from the peaks — the echo itself given form.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienYamabiko.jpg?width=1024"},{"name":"Tenome","rarity":"common","id":"tenome","subtitle":"Yokai","details":"In Japanese folklore, the tenome is a blind-seeming old man whose eyes sit in the palms of his hands, hunting by scent at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienTenome.jpg?width=1024"},{"name":"Mujina","rarity":"common","id":"mujina","subtitle":"Yokai","details":"In Japanese folklore, the mujina is a shape-shifting badger-like yokai, sometimes imagined as a faceless figure that terrifies night travelers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienMujina.jpg?width=1024"},{"name":"Waira","rarity":"common","id":"waira","subtitle":"Yokai","details":"In Japanese folklore, the waira is a hulking, seldom-seen mountain beast known only from old reports, with great claws for digging.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienWaira.jpg?width=1024"},{"name":"Leprechaun","rarity":"common","id":"leprechaun","subtitle":"Mythical Creature","details":"Irish folklore tells of the solitary shoemaker fairy who hoards a crock of gold.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leprechaun%20ill%20artlibre%20jnl.png?width=1024"},{"name":"Draugr","rarity":"common","id":"draugr","subtitle":"Mythical Creature","details":"Norse tales describe the restless dead who guard their burial mounds with undead strength.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant%20draugr%20by%20Kim%20Diaz%20Holm%20(cropped).jpg?width=1024"},{"name":"Garmr","rarity":"common","id":"garmr","subtitle":"Mythical Creature","details":"In Norse myth, the blood-stained hound of Hel who breaks free and howls before Ragnarök.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%B6lva%2C%20Odin%2C%20Sleipnir%20and%20Helhound%20by%20Fr%C3%B8lich.jpg?width=1024"},{"name":"Hildisvíni","rarity":"common","id":"hildisvini","subtitle":"Mythical Creature","details":"In Norse myth, Freyja's golden-bristled battle boar, her lover Óttarr in disguise.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%93ttarr%20by%20Fr%C3%B8lich.jpg?width=1024"},{"name":"Sköll & Hati","rarity":"common","id":"skoll-hati","subtitle":"Mythical Creature","details":"In Norse myth, the wolves who chase the sun and moon, and will catch them at Ragnarök.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Wolves%20Pursuing%20Sol%20and%20Mani.jpg?width=1024"},{"name":"Mari Lwyd","rarity":"common","id":"mari-lwyd","subtitle":"Mythical Creature","details":"Welsh tradition tells of the decorated horse skull that visits homes singing rhyming verses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mari%20Lwyd%20NLW.jpg?width=1024"},{"name":"Cŵn Annwn","rarity":"common","id":"cwn-annwn","subtitle":"Mythical Creature","details":"Welsh tales describe the white hounds with red ears that hunt the souls of the dead.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Lords%20of%20Annwn.jpg?width=800"},{"name":"Nuckelavee","rarity":"common","id":"nuckelavee","subtitle":"Mythical Creature","details":"Orcadian folklore tells of the skinless demon, half man and half horse, rising from the sea.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/nuckelavee.webp"},{"name":"Redcap","rarity":"common","id":"redcap","subtitle":"Mythical Creature","details":"Border folklore tells of the goblin whose cap must be dipped in the blood of his victims.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Redcaps%20of%20Kerleau%20-%20T.%20R.%20Macquoid.png?width=800"},{"name":"Brownie","rarity":"common","id":"brownie","subtitle":"Spirit","details":"Scottish folklore tells of the helpful house spirit who labors at night for a bowl of cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20of%20a%20brownie%20by%20Alice%20B%20Woodward.jpg?width=1024"},{"name":"Spriggan","rarity":"common","id":"spriggan","subtitle":"Mythical Creature","details":"Cornish tales describe the ugly fairy guardians of hill treasures, able to swell to giant size.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spriggan%20sculpture%20by%20Marilyn%20Collins%2C%20Parkland%20Walk%2C%20Haringey.jpg?width=1024"},{"name":"Ellyll","rarity":"common","id":"ellyll","subtitle":"Mythical Creature","details":"Welsh folklore tells of the tiny elves who haunt the groves and meadows of Wales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rowli%20and%20the%20Ellyll%20from%20British%20Goblins%20Welsh%20folk-lore%2C%20fairy%20mythology%2C%20legends%20and%20traditions%20by%20Wirt%20Sikes%20(1880).jpg?width=1024"},{"name":"Ghillie Dhu","rarity":"common","id":"ghillie-dhu","subtitle":"Spirit","details":"Scottish tales describe the gentle wild man of the woods, guardian of the birch trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ghillie-Dhu%20-%20geograph.org.uk%20-%203160913.jpg?width=1024"},{"name":"Fachan","rarity":"common","id":"fachan","subtitle":"Mythical Creature","details":"Scottish folklore tells of the one-eyed, one-legged monster of the highland glens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Direach%20Ghlinn%20Eiti%20or%20Fachan.jpg?width=1024"},{"name":"Ceffyl Dŵr","rarity":"common","id":"ceffyl-dwr","subtitle":"Mythical Creature","details":"Welsh tales describe the water horse that lures travelers into deep, still pools.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Globe%20fountain%20detail%20-%20geograph.org.uk%20-%20894643.jpg?width=1024"},{"name":"Bogle","rarity":"common","id":"bogle","subtitle":"Mythical Creature","details":"Scottish and northern English tales describe the mischievous goblin that haunts dark places.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Page%20212%20illustration%20in%20English%20Fairy%20Tales.png?width=1024"},{"name":"Fossegrim","rarity":"common","id":"fossegrim","subtitle":"Spirit","details":"Norwegian folklore tells of the water spirit whose fiddle can make trees and water dance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bergslien%20Fossegrimen.jpg?width=1024"},{"name":"Nøkken","rarity":"common","id":"nkken","subtitle":"Spirit","details":"Scandinavian folklore tells of the shape-shifting water spirit who lures folk with his song.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kittelsen%20-%20N%C3%B8kken%20(Nasjonalmuseet)2.jpg?width=1024"},{"name":"Mare","rarity":"common","id":"mare","subtitle":"Spirit","details":"Northern European tales describe the night spirit who sits on sleepers' chests and steals breath.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zmora%20dusz%C4%85ca%20cz%C5%82owieka.jpg?width=800"},{"name":"Corrigan","rarity":"common","id":"corrigan","subtitle":"Mythical Creature","details":"Breton folklore tells of the dancing korrigans, fairies of the moors and standing stones.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/corrigan.webp"},{"name":"Bishop Fish","rarity":"common","id":"bishop-fish","subtitle":"Sea Monster","details":"Medieval chronicles told of a Bishop Fish, a sea creature shaped like a bishop in robes and mitre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20bishop%20%281669%29.jpg?width=1024"},{"name":"Sea Monk","rarity":"common","id":"sea-monk","subtitle":"Sea Monster","details":"Sixteenth-century naturalists described the Sea Monk, a fish said to resemble a robed monk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20monk%20%281669%29.jpg?width=1024"},{"name":"Bahamut","rarity":"common","id":"bahamut","subtitle":"Sea Monster","details":"In Arabian cosmology, Bahamut is a colossal fish that carries the bull Kujata and the whole world above it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Al%20Qazwini%20Cosmology.jpg?width=1024"},{"name":"Zaratan","rarity":"common","id":"zaratan","subtitle":"Sea Monster","details":"Arabic sailors' tales told of the Zaratan, a giant sea creature whose island-like back fooled landing crews.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alexander%20Romance%2C%20Armenian%20manuscript%2C%201538%E2%80%931544.jpg?width=1024"},{"name":"Giant Octopus","rarity":"common","id":"giant-octopus","subtitle":"Sea Monster","details":"Old sailors' reports described a giant octopus able to pull ships and crews down into the sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant%20octopus%20attacks%20ship.jpg?width=1024"},{"name":"Mami Wata","rarity":"common","id":"mami-wata","subtitle":"Sea Monster","details":"In West and Central African tradition, Mami Wata is a beautiful water spirit linked to wealth and luck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mami%20Wata%20Figure%20MIA.jpg?width=1024"},{"name":"Anqa","rarity":"common","id":"anqa","subtitle":"Mythical Creature","details":"In Arabian folklore, the Anqa is a huge, wise bird that lives apart from humankind for ages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NLM%20MS%20P%202-fol187b-anqa.jpg?width=640"},{"name":"Oxumare","rarity":"common","id":"oxumare","subtitle":"Mythical Creature","details":"In Yoruba tradition, Oxumare is a rainbow serpent who moves between sky and earth, bringing renewal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caryb%C3%A8%2C%20rilievi%20degli%20orixas%2C%20oxumare%2002.JPG?width=800"},{"name":"Melusine","rarity":"common","id":"melusine","subtitle":"Sea Monster","details":"In French tradition, Melusine is a water spirit who took a serpent's form one day each week and founded the house of Lusignan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melusine%20%28Paris%2C%20Michel%20Le%20Noir%2C%201517%29.jpg?width=800"},{"name":"Norwegian Sea Serpent","rarity":"common","id":"norwegian-sea-serpent","subtitle":"Sea Monster","details":"Olaus Magnus pictured a great sea serpent off Norway in 1555, said to snatch sailors from their ships.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Soe%20Orm%201555.jpg?width=1024"},{"name":"Maned Sea Serpent","rarity":"common","id":"maned-sea-serpent","subtitle":"Sea Monster","details":"Eighteenth-century accounts from Norway described a sea serpent with a mane flowing behind its head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maned%20sea%20serpent%201755.jpg?width=1024"},{"name":"Pania","rarity":"common","id":"pania","subtitle":"Sea Monster","details":"Maori legend tells of Pania, a sea maiden of Napier who was turned to stone on the reef.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pania%20of%20the%20Reef%20a%20%28cropped%291.jpg?width=800"},{"name":"Alkonost","rarity":"common","id":"alkonost","subtitle":"Mythical Creature","details":"In Slavic legend, Alkonost is a bird with a woman's head whose song brings joy and forgetfulness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sirin%20and%20Alkonost%20by%20Vasnetsov%20%28GTG%29%2002%20by%20shakko.jpg?width=1024"},{"name":"Sirin","rarity":"common","id":"sirin","subtitle":"Mythical Creature","details":"In Slavic legend, Sirin is a bird with a woman's head whose beautiful song lures listeners to their doom.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/sirin.webp"},{"name":"Ningyo","rarity":"common","id":"ningyo","subtitle":"Sea Monster","details":"In Japanese folklore, the ningyo is a fish-bodied creature with a human face, said to foretell storms and misfortune.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nagasaki%20bunkenroku%20nukigaki-colored-kaijo%28ningyo%29.png?width=500"},{"name":"Rusalka","rarity":"common","id":"rusalka","subtitle":"Sea Monster","details":"In Slavic tradition, the rusalka is a water spirit said to haunt rivers and lakes and lure the unwary to the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rusalka%20Bilibin.jpg?width=1024"},{"name":"Sedna","rarity":"common","id":"sedna","subtitle":"Sea Monster","details":"In Inuit tradition, Sedna is the sea woman who lives on the ocean floor and rules over its animals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sanna%20aux%20doigts%20coup%C3%A9s.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
